head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;
scwin.gViewerStat = "P";
scwin.gIsurCd;
// js_team
// page 변수.
scwin.pageSize = 10; //페이지 size
scwin.totalCnt = 0; //전체 row
scwin.pageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.gParamObj = new Array(4);
scwin.gISUR_CD;
scwin.gCOM_NM;
scwin.vScrenID = 'ULDSTF30000.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    $c.stf.showObj(grd_Tab3_List, false);
    $c.stf.showObj(panel_mkt, false);
    $c.stf.showObj(panel_mkt2, false);
    $c.stf.showObj(panel_mkt3, false);
    $c.stf.showObj(panel_mkt4, false);
    dts_Tab1_Emp.UseFilter = true;
    dts_Tab3_Emp.UseFilter = true;
    dts_Tab4_Emp.UseFilter = true;
    if (scwin.gLdMktTp == "9") {
        $c.stf.showObj(panel_mkt, true);
        $c.stf.showObj(panel_mkt2, true);
        $c.stf.showObj(panel_mkt3, true);
        $c.stf.showObj(panel_mkt4, true);
        $c.stf.setObjectValue(rdo_Tab1_Market_Flag, "2");
        $c.stf.setObjectValue(rdo_Tab2_Market_Flag, "2");
        $c.stf.setObjectValue(rdo_Tab3_Market_Flag, "2");
        $c.stf.setObjectValue(rdo_Tab4_Market_Flag, "2");
    } else {
        $c.stf.setObjectValue(rdo_Tab1_Market_Flag, scwin.gLdMktTp);
        $c.stf.setObjectValue(rdo_Tab2_Market_Flag, scwin.gLdMktTp);
        $c.stf.setObjectValue(rdo_Tab3_Market_Flag, scwin.gLdMktTp);
        $c.stf.setObjectValue(rdo_Tab4_Market_Flag, scwin.gLdMktTp);
    }

    // TAB1
    $c.stf.setObjectValue(edt_Tab1_SDate, $c.ut.cGetToday2());

    //setObjectValue(edt_Tab1_EDate, calcMonth(cGetToday2(), 1));	2009.08.28 하루만 조회되도록 변경
    $c.stf.setObjectValue(edt_Tab1_EDate, $c.ut.cGetToday2());
    $c.stf.setObjectValue(cmb_Tab1_Dep, js_dep_cd);
    $c.stf.setObjectValue(cmb_Tab1_Emp, js_emp_no);
    dts_Tab1_Emp.Filter();

    // TAB2
    $c.stf.PanelMsg(panel_page_tab2_2, "시장안내공시");
    //setObjectValue(cmb_PeriodTp2, "1");	
    $c.stf.setObjectValue(edt_Tab2_SDate, $c.ut.cGetToday2());


    // TAB3	
    //공시사유코드
    var url = "/DisclosureSchedule.do?method=listDsclRsnCode&MKT_ID=" + $c.stf.getObjectValue(rdo_Tab3_Market_Flag);
    //alert(url);
    dts_RSN.DataID = encodeURI(url);
    dts_RSN.Reset();
    $c.stf.setObjectValue(cmb_PeriodTp_Tab3, "5");
    $c.stf.setObjectValue(cmb_Tab3_Dep, js_dep_cd);
    $c.stf.setObjectValue(cmb_Tab3_Emp, js_emp_no);
    dts_Tab3_Emp.Filter();

    // TAB4
    $c.stf.setObjectValue(cmb_Tab4_Dep, js_dep_cd);
    $c.stf.setObjectValue(cmb_Tab4_Emp, js_emp_no);
    $c.stf.setObjectValue(edt_Tab4_SDate, $c.ut.cGetToday2());
    $c.stf.setObjectValue(edt_Tab4_EDate, $c.ut.cGetToday2());
    dts_Tab4_Emp.Filter();

    // 디폴트 검색 
    scwin.fn_Search();
};
scwin.fn_SetHeader = function() {
    dts_Search_Tab1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SCHEDULE_IN";
    dts_Search_Tab1.Reset();
    dts_Save.AddRow();
    //alert("fn_SetHeader = " + dts_Search_Tab1.Text);

};
scwin.fn_SetCode = function() {
    var url_DepCD = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    var url_EmpCD = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_Tab1_Emp.DataID = url_EmpCD;
    dts_Tab1_Emp.Reset();
    dts_Tab1_Dep.DataID = url_DepCD;
    dts_Tab1_Dep.Reset();
    dts_Tab3_Emp.DataID = url_EmpCD;
    dts_Tab3_Emp.Reset();
    dts_Tab3_Dep.DataID = url_DepCD;
    dts_Tab3_Dep.Reset();
    dts_Tab4_Emp.DataID = url_EmpCD;
    dts_Tab4_Emp.Reset();
    dts_Tab4_Dep.DataID = url_DepCD;
    dts_Tab4_Dep.Reset();
    dts_Status_Tab1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SCHEDULE_IN";
    dts_Status_Tab1.Reset();
    dts_Tab1_Status.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=DISCLS_SCHDL_ACT_STAT_CD";
    dts_Tab1_Status.Reset();
};
scwin.fn_CheckTab1Cond = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_Tab1_SDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_Tab1_SDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_Tab1_EDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_Tab1_EDate.focus();
        return;
    }
    scwin.fn_Search();
};
scwin.fn_CheckTab4Cond = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_Tab4_SDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_Tab4_SDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_Tab4_EDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_Tab4_EDate.focus();
        return;
    }
    scwin.fn_Date_Search();
};
scwin.fn_SearchMain = function() {
    if (MxTab_1.getSelectedTabIndex() == 1) {
        scwin.fn_Search();
    } else if (MxTab_1.getSelectedTabIndex() == 2) {
        scwin.fn_Daily_Search();
    } else if (MxTab_1.getSelectedTabIndex() == 3) {
        scwin.fn_listDisclosureReason();
    } else if (MxTab_1.getSelectedTabIndex() == 4) {
        scwin.fn_Date_Search();
    }
};
scwin.fn_Search = function() {
    var edt_FromDate_year = $c.stf.getObjectValue(edt_Tab1_SDate).substr(0, 4);
    var edt_FromDate_month = $c.stf.getObjectValue(edt_Tab1_SDate).substr(4, 2) - 1;
    var edt_FromDate_day = $c.stf.getObjectValue(edt_Tab1_SDate).substr(6, 2);
    var edt_FromDate_Date = new Date(edt_FromDate_year, edt_FromDate_month, edt_FromDate_day);
    var edt_ToDate_year = $c.stf.getObjectValue(edt_Tab1_EDate).substr(0, 4);
    var edt_ToDate_month = $c.stf.getObjectValue(edt_Tab1_EDate).substr(4, 2) - 1;
    var edt_ToDate_day = $c.stf.getObjectValue(edt_Tab1_EDate).substr(6, 2);
    var edt_ToDate_Date = new Date(edt_ToDate_year, edt_ToDate_month, edt_ToDate_day);


    // 1년 이상의 기간은 검색 할 수 없다
    var date_result = (Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date)) / (1000 * 60 * 60 * 24);
    if (date_result > 365) {
        $c.win.alert("검색기간은 1년을 초과할 수 없습니다.");
        return;
    }
    $c.cm.ShowWin(grd_Tab1_List);
    var MKT_ID = $c.stf.getObjectValue(rdo_Tab1_Market_Flag);
    var ISUR_CD = $c.stf.getObjectValue(txb_Tab1_IsurCd);
    var COMNM = $c.stf.getObjectValue(txb_Tab1_ComNm);
    var SDATE = $c.stf.getObjectValue(edt_Tab1_SDate);
    var EDATE = $c.stf.getObjectValue(edt_Tab1_EDate);
    var DEPCD = $c.stf.getObjectValue(cmb_Tab1_Dep);
    var EMPNO = $c.stf.getObjectValue(cmb_Tab1_Emp);
    var RPTCD = $c.stf.getObjectValue(txb_Tab1_RptCd);
    var RPTNM = $c.stf.getObjectValue(txb_Tab1_RptNm);
    var STATUSCD = $c.stf.getObjectValue(cmb_Tab1_Status);
    var ACT_YN = $c.stf.getObjectValue(chb_Tab1_Act_Yn);
    var url = "/DisclosureSchedule.do?method=listSchedule";
    url += "&MKT_ID=" + MKT_ID;
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&DEPCD=" + DEPCD;
    url += "&EMPNO=" + EMPNO;
    url += "&TEAM_ID=" + js_team;
    url += "&RPTCD=" + RPTCD;
    url += "&STATUSCD=" + STATUSCD;
    url += "&ACT_YN=" + ACT_YN;
    url += "&SUBMIT_SYS_USE_YN=" + $c.stf.getObjectValue(cmb_SUBMIT_SYS_USE_YN);
    url += "&SMS_TRNSM_YN=" + $c.stf.getObjectValue(cmb_SMS_TRNSM_YN);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert(encodeURI(url));
    dts_Grid_Tab1.DataID = encodeURI(url);
    dts_Grid_Tab1.Reset();
};
scwin.fn_Daily_Search = function() {
    if ($c.stf.getObjectValue(edt_Tab2_SDate) == "") {
        $c.win.alert("[일별시장조치 기준-시작일]를 입력하세요.");
        edt_Tab2_SDate.focus();
        return;
    }
    $c.cm.ShowWin(grd_Tab2_List);
    var url = "/DisclosureSchedule.do?method=listDailyMarket";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_Tab2_Market_Flag);
    url += "&STRD_DATE=" + $c.stf.getObjectValue(edt_Tab2_SDate);
    url += "&END_DATE=" + $c.stf.getObjectValue(edt_Tab2_SDate); // 하루만 넘기기는 걸로 바꿨음.(서버코딩없이 클라이언트만 당일이 넘어가게 수정)
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert(encodeURI(url));
    dts_Grid_Tab2.DataID = encodeURI(url);
    dts_Grid_Tab2.Reset();

    // 시장안내공시 n건
    url = "/DisclosureSchedule.do?method=listDailyMarketDscl";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_Tab2_Market_Flag);
    url += "&STRD_DATE=" + $c.stf.getObjectValue(edt_Tab2_SDate);
    url += "&END_DATE=" + $c.stf.getObjectValue(edt_Tab2_SDate);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid_Tab2_2.DataID = encodeURI(url);
    dts_Grid_Tab2_2.Reset();
};
scwin.fn_listDisclosureReason = function() {
    var ISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var SDATE = $c.stf.getObjectValue(edt_Tab3_SDate);
    var EDATE = $c.stf.getObjectValue(edt_Tab3_EDate);
    if (SDATE > EDATE) {
        $c.win.alert("검색시작일은 검색종료일보다 앞설 수 없습니다.");
        return;
    }
    var DEPCD = $c.stf.getObjectValue(cmb_Tab3_Dep);
    var EMPNO = $c.stf.getObjectValue(cmb_Tab3_Emp);
    var LIST_STAT = scwin.getChkValue(chb_LIST_STAT_CD);
    var STATUS = $c.stf.getObjectValue(cmb_Tab3_Status);
    var RSN_CD = "";
    for (var i = 0; i < dts_RSN.getTotalRow(); i++) {
        for (var j = 0; j < 5; j++) {
            var tmp = dts_RSN.getCellData(i, "CHK" + (j + 1));
            if (tmp == "T" || tmp == 1) {
                var tmp2 = dts_RSN.getCellData(i, "COL_CD" + (j + 1));
                RSN_CD += tmp2 + "|";
            }
        }
    }
    // 위치.크기 바꾸기.
    $c.stf.SetWindowPos(grd_Tab3_List, grd_RSN.style.top, grd_RSN.style.left, grd_RSN.getStyle("width"), grd_RSN.getStyle("height"));
    $c.stf.showObj(grd_RSN, false);
    $c.stf.showObj(grd_Tab3_List, true);
    $c.cm.ShowWin(grd_Tab3_List);
    var url = "/DisclosureSchedule.do?method=listDisclosureReason";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_Tab3_Market_Flag);
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&DEPCD=" + DEPCD;
    url += "&EMPNO=" + EMPNO;
    url += "&TEAM_ID=" + js_team;
    url += "&STATUS=" + STATUS;
    url += "&LIST_STAT=" + LIST_STAT;
    url += "&RSN_CD=" + RSN_CD;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert(encodeURI(url));
    dts_Grid_Tab3.DataID = encodeURI(url);
    dts_Grid_Tab3.Reset();
};
scwin.getChkValue = function(obj) {
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.fn_Date_Search = function() {
    var edt_FromDate_year = $c.stf.getObjectValue(edt_Tab4_SDate).substr(0, 4);
    var edt_FromDate_month = $c.stf.getObjectValue(edt_Tab4_SDate).substr(4, 2) - 1;
    var edt_FromDate_day = $c.stf.getObjectValue(edt_Tab4_SDate).substr(6, 2);
    var edt_FromDate_Date = new Date(edt_FromDate_year, edt_FromDate_month, edt_FromDate_day);
    var edt_ToDate_year = $c.stf.getObjectValue(edt_Tab4_EDate).substr(0, 4);
    var edt_ToDate_month = $c.stf.getObjectValue(edt_Tab4_EDate).substr(4, 2) - 1;
    var edt_ToDate_day = $c.stf.getObjectValue(edt_Tab4_EDate).substr(6, 2);
    var edt_ToDate_Date = new Date(edt_ToDate_year, edt_ToDate_month, edt_ToDate_day);


    // 1년 이상의 기간은 검색 할 수 없다
    var date_result = (Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date)) / (1000 * 60 * 60 * 24);
    if (date_result > 365) {
        $c.win.alert("검색기간은 1년을 초과할 수 없습니다.");
        return;
    }
    $c.cm.ShowWin(grd_Tab4_List);
    var ISUR_CD = $c.stf.getObjectValue(txb_Tab4_IsurCd);
    var SDATE = $c.stf.getObjectValue(edt_Tab4_SDate);
    var EDATE = $c.stf.getObjectValue(edt_Tab4_EDate);
    var DEPCD = $c.stf.getObjectValue(cmb_Tab4_Dep);
    var EMPNO = $c.stf.getObjectValue(cmb_Tab4_Emp);
    //var LIST_STAT = getObjectValue(chb_Tab4_Activ_Yn);

    var url = "/DisclosureSchedule.do?method=listDisclosureDate";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_Tab4_Market_Flag);
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&DEPCD=" + DEPCD;
    url += "&EMPNO=" + EMPNO;
    url += "&TEAM_ID=" + js_team;
    url += "&LIST_STAT=";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert(encodeURI(url));
    dts_Grid_Tab4.DataID = encodeURI(url);
    dts_Grid_Tab4.Reset();
};
scwin.fn_readSchedule = async function(GridID, row, colid) {
    if (row < 1) return;
    var CMD = "R";
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var DISCLS_SCHDL_ADM_DD = objDataID.getCellData(row, "DISCLS_SCHDL_ADM_DD");
    var BYDD_SEQ = objDataID.getCellData(row, "BYDD_SEQ");
    var USR_ID = objDataID.getCellData(row, "INTEG_USR_ID");
    var SCHDL_TP_CD = objDataID.getCellData(row, "SCHDL_TP_CD");
    if (colid == "CD_NM" || colid == "SCHDL_CONFRM_YN") {
        if (scwin.fn_setParam(CMD, DISCLS_SCHDL_ADM_DD, BYDD_SEQ, USR_ID)) // formal arguments

        {
            var winTitle = "일정조회";
            if (SCHDL_TP_CD == "5" || SCHDL_TP_CD == "6") {
                var url = "/dsclmgt/ULDSTF30012.gfm";
                await $c.frame.CreateFrame("ULDSTF30012", url, winTitle, 10, 10, 10, 20, "window", 0, 0, true);
            } else {
                var url = "/dsclmgt/ULDSTF30001.gfm";
                await $c.frame.CreateFrame("ULDSTF30001", url, winTitle, 10, 10, 10, 20, "window", 0, 0, true);
                //frame.CreateDialogFrame("child01", "/dsclmgt/ULDSTF30001.gfm", "일정조회", 10, 10, 10, 20, "window");

            }
        }
    } else if (colid == "DISCLS_TITLE") {
        var AcptNo = objDataID.getCellData(row, "ACPT_NO");
        $c.stf.fn_OpenDisclViewer(AcptNo, "R");
    } else if (colid == "COM_ABBRV") {
        scwin.gIsurCd = objDataID.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "SUBMIT_SYS_USE_YN" || colid == "SMS_TRNSM_YN") {
        var url = "/dsclmgt/ULDSTF30011.gfm";
        var winTitle = "상장법인공개목록";
        //frame.CreateFrame("ULDSTF30011", url , winTitle , 10, 10, 10, 20, "window", 0, 0, true);	
        $c.frame.path("/top").WinOpen("ULDSTF30011", url, winTitle, 607, 480);
    }
};



// paramObj Update
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.fn_IsEngChar = function(str) {
    var re = /[^-a-z_A-Z]/; // 영문자가 아닌 게 있는 걸 찾아라.
    return !re.test(str);
};
scwin.fn_HideGridCol = function(GridID) {
    var ColCnt = GridID.getTotalCol();
    for (var i = 0; i < ColCnt; i++) {
        var ColID = GridID.GetColumnID(i);
        var HeaderNm = GridID.GetHdrDispName(-3, ColID);
        if (scwin.fn_IsEngChar(HeaderNm)) {
            // 영문 컬럼이면 숨겨라.
            GridID.setColumnProp(ColID, "Show", false);
        }
    }
};
scwin.fn_HideDebugCtrls = function() {
    scwin.fn_HideGridCol(grd_Tab1_List);
    scwin.fn_HideGridCol(grd_Tab2_List);
    scwin.fn_HideGridCol(grd_Tab3_List);
    scwin.fn_HideGridCol(grd_Tab4_List);

    //showObj(panel_debug, false);	

};
scwin.openNew = async function() {
    if (scwin.fn_setParam()) // 신규모드 param이 없다.

    {
        var url = "/dsclmgt/ULDSTF30001.gfm";
        var winTitle = "신규";
        await $c.frame.CreateFrame("ULDSTF30001", url, winTitle, 10, 10, 10, 20, "window", 0, 0, true);
