    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    if (nIndex == 1) {
        // 첫번째 탭 클릭시 		
        scwin.fn_Search();
    } else if (nIndex == 2) {
        // 두번째 탭 클릭시 
        scwin.fn_Daily_Search();
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_monthly_notices_onclick = function() {
    scwin.fn_openMonthlyNoti();
};
scwin.btn_schedule_onclick = async function() {
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF30006.gfm", "공시일정추출현황", 300, 100, 1300, 750, "window");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_7);
    $c.cm.PanelToGroupBox(panel_8);
    MxTab_1.setSelectedTabIndex("1");
    scwin.fn_SetCode();

    // debug 용 콘트롤들 모두 숨기기.
    scwin.fn_HideDebugCtrls();
    scwin.fn_Init();
    $c.cm.fn_com_isur(txb_Tab1_IsurCd, txb_Tab1_ComNm);

    // 코스닥일때만 상장법인공개여부,SMS전송여부 보여준다. -> 이 화면은 코스닥만 사용!
    if (scwin.gDepCd.substring(0, 2) != '34') {
        $c.stf.showObj(btn_monthly_notices, false);
        $c.stf.showObj(label_18, false);
        $c.cm.setColumnProp(grd_Tab1_List, 'SUBMIT_SYS_USE_YN', 'Show', false);
        $c.cm.setColumnProp(grd_Tab1_List, 'SMS_TRNSM_YN', 'Show', false);
    }
    /**
	if(gLdMktTp != '2') {
grd_Tab1_List.setColumnProp('SUBMIT_SYS_USE_YN','Show',false) ;
grd_Tab1_List.setColumnProp('SMS_TRNSM_YN','Show',false) ;
	}
	*/
};
